  if(!compact)for(let i=series.length-1;i>=0;i--)if(scoresHiddenYears.has(series[i].year))series.splice(i,1);
  const w=compact?700:1200,h=compact?410:620,l=76,r=compact?58:34,t=32,b=54;
  const scale=!compact&&['all','aga'].includes(scoresGeography)&&['all','regular'].includes(scoresPopulation)?{min:3000000,max:12000000,ticks:[3000000,4500000,6000000,7500000,9000000,10500000,12000000]}:summaryAxis(series.length?series.flatMap(s=>s.rows.map(r=>r.count)):[0,1]);
