  let svg=`<div class="chart summary-trend-chart ${compact?'':'scores-wide-trend'}"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Monthly scores by year: ${series.map(s=>s.year).join(', ')}">`;
  scale.ticks.forEach(v=>{svg+=`<line class="gridline" x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}"/><text class="axis-label y-tick" x="${l-12}" y="${y(v)+5}" text-anchor="end">${short(v)}</text>`});
  meta.months.forEach((m,i)=>{svg+=`<line class="gridline vertical" x1="${x(i)}" x2="${x(i)}" y1="${t}" y2="${h-b}"/><text class="axis-label" x="${x(i)}" y="${h-18}" text-anchor="middle">${m}</text>`});
  svg+=`<line class="axis" x1="${l}" x2="${l}" y1="${t}" y2="${h-b}"/><line class="axis" x1="${l}" x2="${w-r}" y1="${h-b}" y2="${h-b}"/>`;
