function liveScoresPerformance(d,includeTotal=false,twoYear=null){return `<div class="performance-row reporting-row">${includeTotal?`<div class="performance-block"><div class="performance-label">August Total</div><div class="performance-value report-value">${fmt(d.latest)}</div><div class="performance-period">All Associations · trials included</div></div>`:''}<div class="performance-block"><div class="performance-label">Monthly Change</div><div class="performance-value ${scoreChangeClass(d.monthly)}">${scoreChangeText(d.monthly)}</div><div class="performance-period">vs July 2026</div></div><div class="performance-block"><div class="performance-label">Year-over-Year Change</div><div class="performance-value ${scoreChangeClass(d.monthYoy)}">${scoreChangeText(d.monthYoy)}</div><div class="performance-period">vs August 2025</div></div>${twoYear!==null?`<div class="performance-block"><div class="performance-label">2 Year Change</div><div class="performance-value ${scoreChangeClass(twoYear)}" data-two-year-change>${scoreChangeText(twoYear)}</div><div class="performance-period">vs August 2024</div></div>`:''}</div>`}
let scoresAnnualTotalsView='bars';
