  for(let j=0;j<=4;j++){const v=top*j/4;svg+=`<line class="gridline" x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}"/><text class="axis-label" x="${l-10}" y="${y(v)+4}" text-anchor="end">${short(v)}</text>`;}
  rows.forEach((row,i)=>{if((i%3===0&&i<rows.length-2)||i===rows.length-1)svg+=`<text class="axis-label" x="${x(i)}" y="${h-20}" text-anchor="middle">${meta.months[Number(row.month.slice(5))-1]} '${row.month.slice(2,4)}</text>`;});
  for(const item of items){svg+=`<path fill="none" stroke="${item.color}" stroke-width="3" d="${rows.map((row,i)=>`${i?'L':'M'}${x(i)} ${y(row.methods[item.key]||0)}`).join(' ')}"/>`;rows.forEach((row,i)=>{const n=row.methods[item.key]||0;svg+=`<circle class="line-data-point" data-monthly-category="${esc(item.key)}" data-month="${row.month}" data-count="${n}" data-base-r="3" data-period="${row.month}" data-series="${esc(item.label)}" data-value="${fmt(n)} scores" cx="${x(i)}" cy="${y(n)}" r="3" fill="${item.color}"><title>${row.month} · ${esc(item.label)}: ${fmt(n)}</title></circle>`;});}
