  const summary=chartDataDisclosure(items.map(i=>({...i,attributes:`data-${attribute}-category="${esc(i.key)}" data-${attribute}-count="${i.value}"`})),total).replace('Data breakdown</caption>','January–August 2026 summary</caption>');
  const monthly=`<div class="scores-monthly-data-scroll"><table class="scores-monthly-data"><caption>${monthlyMode?'Monthly score counts':'Annual score totals · 2026 is incomplete'}</caption><thead><tr><th scope="col">${monthlyMode?'Month':'Year / coverage'}</th>${items.map(i=>`<th scope="col">${esc(i.label)}</th>`).join('')}<th scope="col">Total</th></tr></thead><tbody>${rows.map(row=>`<tr><th scope="row">${row.label}${row.partial?' · '+row.period:''}</th>${items.map(i=>`<td>${fmt(row.methods[i.key])}</td>`).join('')}<td>${fmt(items.reduce((n,i)=>n+row.methods[i.key],0))}</td></tr>`).join('')}</tbody></table></div>`;
