function liveScoreHistorySnapshot(items,total){
  let angle=-90,paths='',labels='';
  for(const item of items){if(!item.value)continue;const share=item.value/total,sweep=share*360,mid=(angle+sweep/2)*Math.PI/180,x=50+35*Math.cos(mid),y=50+35*Math.sin(mid);paths+=`<path class="scores-donut-slice" d="${scoresDonutArcPath(angle,sweep)}" fill="${item.color}" data-category="${esc(item.label)}" data-count="${fmt(item.value)}" data-share="${pct(share)}" tabindex="0"><title>${esc(item.label)}: ${fmt(item.value)} (${pct(share)})</title></path>`;if(share>=.07)labels+=`<text class="scores-donut-label" x="${x}" y="${y-2}"><tspan class="scores-donut-label-name" x="${x}">${esc(item.label)}</tspan><tspan class="scores-donut-label-value" x="${x}" dy="5.2">${pct(share)}</tspan></text>`;angle+=sweep;}
  return total?`<div class="scores-type-donut-body"><div class="scores-type-donut"><svg viewBox="0 0 100 100" role="img" aria-label="Year-to-date score distribution">${paths}${labels}</svg><div><strong>${short(total)}</strong><span>Scores</span></div></div></div>`:'<div class="scores-method-empty">No scores for this selection.</div>';
}
function liveScoreHistoryCard(kind,title){
  const data=liveScoreData(),months=data.demographicMonths||data.historicalMonths||[],view=['trend','ytd'].includes(scoresHistoryViews[kind])?scoresHistoryViews[kind]:'snapshot',totals={},dimension=kind==='club'?'clubGroup':kind;
  const selectedMonths=view==='snapshot'?months.filter(m=>m.month.startsWith('2026-')):liveScoreComparisonRows(months,view);
  for(const row of selectedMonths)for(const [k,n]of Object.entries(row.breakdowns[dimension]))totals[k]=(totals[k]||0)+n;
  const colors=['#173d66','#819fbc','#a9bdd2','#60748c','#c8d5e2','#527ca4','#8795a5','#b4bec8','#455e79','#d8e0e8'];
  const keys=Object.keys(totals).sort((a,b)=>kind==='age'?(['Under 13','13–17','18–24','25–34','35–44','45–54','55–64','65–74','75+','Unknown'].indexOf(a)-['Under 13','13–17','18–24','25–34','35–44','45–54','55–64','65–74','75+','Unknown'].indexOf(b)):totals[b]-totals[a]);
  const items=keys.map((key,i)=>({key,label:key,value:totals[key],color:colors[i%colors.length]})),rows=liveScoreComparisonRows(months,view).map(m=>({month:m.month,methods:Object.fromEntries(items.map(i=>[i.key,m.breakdowns[dimension][i.key]||0]))})),total=selectedMonths.reduce((n,m)=>n+m.count,0);
  const coverage=months.length?`${months[0].month.slice(0,4)}–${months.at(-1).month.slice(0,4)}`:'No data';
  let footer=view==='snapshot'?chartDataDisclosure(items.map(i=>({...i,attributes:`data-history-category="${esc(i.key)}" data-history-count="${i.value}"`})),total):liveScoreTrendFooter(rows,items,total,'history',false).replace('January–August 2026 summary',coverage+' combined totals').replace('Annual score totals · 2026 is incomplete',view==='ytd'?'YTD score totals · January–August each year':'Annual score totals · 2026 is incomplete');
  return `<article class="scores-breakdown-card ${['age','club'].includes(kind)?'scores-horizontal-card scores-live-breakdown':'scores-type-donut-card'} blue" data-history-breakdown="${kind}"><div class="scores-card-band has-toggle"><span>${title}</span><div class="scores-type-toggle" role="group" aria-label="${title} view">${[['snapshot','Snapshot'],['ytd','YTD Comparisons'],['trend','Annual Totals']].map(([v,label])=>`<button type="button" data-history-view="${v}" data-history-kind="${kind}" class="${view===v?'active':''}">${label}</button>`).join('')}</div></div><p class="scores-view-period">${view==='snapshot'?'YTD · January–August 2026':coverage+(view==='ytd'?' · January–August each year':' · 2026 through August')}</p>${view==='snapshot'?liveScoreMembershipIndex(kind,items,total):''}${(view==='snapshot'?(kind==='age'?liveScoreAgeBars(items,total):kind==='club'?liveScoreClubBars(items,total):liveScoreHistorySnapshot(items,total)):liveScoreMethodTrend(rows,kind==='age'?items.filter(i=>i.key!=='Unknown'):items,view))+liveScoreChartFooter(footer,`<p class="live-source-note scores-method-note">${view==='snapshot'&&['gender','access'].includes(kind)?'Posting index = category share of YTD scores ÷ category share of active memberships for the selected geography and member type. 1.00× means proportional representation. Memberships include zero posters and may include multiple memberships per golfer; this is not an average per unique golfer. Membership extracts are from September 2026; scores cover January–August. Trial golfers have no matching active-membership baseline. Unknown categories remain in the denominators. All Members scores include trials, while the membership baseline excludes trials. ':''}Gender, age bands and primary-club attributes reflect records at extraction, not posting-time history. Public/private describes club affiliation, not the course played. Unknown records remain included. These demographic exports currently cover ${coverage}. Demographic totals use separately dated exports and can differ slightly from the earlier score totals; association and member classifications may also have changed between extracts.</p>`)}</article>`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-history-view]');if(b&&['snapshot','trend','ytd'].includes(b.dataset.historyView)){scoresHistoryViews[b.dataset.historyKind]=b.dataset.historyView;render();}});
function liveScoresMix(){
  if(SCORE_COUNTS_DATA.meta.postingMethods?.consolidated){
    const group=(id,title,cards)=>`<section class="scores-mix-section" aria-labelledby="${id}"><h3 id="${id}" class="scores-mix-section-heading">${title}</h3><div class="scores-breakdown-grid">${cards}</div></section>`;
    return `<section class="scores-section"><nav class="scores-mix-jump-links" aria-label="Score posting sections">${[['score-types','Score Types'],['score-posting-channels','Score Posting Channels'],['score-demographics','Demographics'],['score-golfer-types','Golfer Types']].map(([id,label])=>`<a href="#${id}">${label}</a>`).join('')}</nav>${group('score-types','Score Types',liveScoresMethodCard()+liveScoresBreakdownCard('holes'))}${group('score-posting-channels','Score Posting Channels',liveScoresBreakdownCard('product')+liveScoresBreakdownCard('api'))}${group('score-demographics','Demographics',liveScoreHistoryCard('age','Scores Posted by Age')+liveScoreHistoryCard('gender','Scores Posted by Gender'))}${group('score-golfer-types','Golfer Types',liveScoreHistoryCard('access','Scores by Public / Private Affiliation')+liveScoreHistoryCard('club','Scores Posted by Club Breakdown')+liveScoresBreakdownCard('membership'))}</section>`;
  }
  // Preserve the original design preview without pretending it uses the live filters.
  const population=scoresPopulation;let preview;
  try{scoresPopulation='all';preview=scoresPostingMix();}finally{scoresPopulation=population;}
  preview=preview.replaceAll('</article>','<p class="scores-mix-sample-note">Sample data · Association and member filters do not apply to this preview.</p></article>');
  if(SCORE_COUNTS_DATA.meta.postingMethods)preview=preview.replace(/<article\b[\s\S]*?<\/article>/,()=>liveScoresMethodCard());
  const trial=liveScoresTrialTile().replace('card full scores-trial-tile','card scores-trial-tile').replace('<div class="scores-trial-body">','<div class="scores-trial-body"><p class="live-source-note">Database counts · selected association and member filters apply.</p>');
  return preview.replace('</div></section></div>',`${trial}</div></section></div>`).replace(/<article\b[^>]*>/g,tag=>{
    const live=/scores-live-method|scores-trial-tile/.test(tag);
    return tag+`<div class="scores-data-status ${live?'is-real':'is-sample'}"><span>${live?'Real data':'Sample data'}</span><small>${live?'Database export · filters apply':'Mock values · filters do not apply'}</small></div>`;
  });
}
let scoresAssociationPeriod='ytd';
function liveScoresAssociations(){
  const data=liveScoreData(),months=data.associationMonths||[],years=[...new Set(months.map(m=>m.month.slice(0,4)))].sort(),current=String(SCORE_COUNTS_DATA.meta.year),prior=String(SCORE_COUNTS_DATA.meta.year-1),groups=new Map(),totals={};
  for(const month of months){if(scoresAssociationPeriod==='ytd'&&Number(month.month.slice(5))>SCORE_COUNTS_DATA.meta.reportMonth)continue;const year=month.month.slice(0,4);for(const a of month.associations){const key=a.scope+':'+a.id;if(!groups.has(key))groups.set(key,{id:a.id,scope:a.scope,name:a.name,years:{},junior:0});const r=groups.get(key);r.years[year]=(r.years[year]||0)+a.scores;if(year===current){r.name=a.name;r.junior+=a.junior;}totals[year]=(totals[year]||0)+a.scores;}}
  const rows=[...groups.values()].map(r=>({...r,scores:r.years[current]||0,scoreYoy:scoresAssociationPeriod==='ytd'?scoreCountChange(r.years[current]||0,r.years[prior]||0):null,juniorPostPct:r.years[current]?r.junior/r.years[current]:0}));
  rows.sort((a,b)=>b.scores-a.scores||a.name.localeCompare(b.name));rows.forEach((r,i)=>r.rank=i+1);
  const change=(counts,year)=>scoresAssociationPeriod==='annual'&&year===current?null:scoreCountChange(counts[year]||0,counts[String(Number(year)-1)]||0);
  const changeCell=(counts,year)=>`<span class="scores-association-change ${scoreChangeClass(change(counts,year))}" data-association-change="${year}">${scoreChangeText(change(counts,year))}</span>`;
  const value=(r,k)=>k==='association'?r.name.toLowerCase():k.startsWith('change-')?(change(r.years,k.slice(7))??-Infinity):k.startsWith('year-')?r.years[k.slice(5)]||0:['scores','share'].includes(k)?r.scores:k==='rank'?-r.rank:r[k]??-Infinity,dir=scoresAssociationSort.direction==='asc'?1:-1;
  rows.sort((a,b)=>{const x=value(a,scoresAssociationSort.key),y=value(b,scoresAssociationSort.key);return (typeof x==='string'?x.localeCompare(y):x-y)*dir||a.rank-b.rank;});
  const header=(key,label)=>`<span role="button" tabindex="0" data-scores-association-sort="${key}">${label} ${scoresAssociationSort.key===key?(dir===1?'▲':'▼'):'↕'}</span>`;
  return `<section class="scores-section scores-associations-section"><p class="live-source-note">${scoresAssociationPeriod==='ytd'?'January–August each year':'2022–2025 full years · 2026 January–August'}</p><article class="scores-ranking-card scores-ranking-full scores-live-ranking scores-association-history ${scoresAssociationPeriod}"><div class="scores-card-band has-toggle"><span>Scores Posted by Association</span><div class="scores-type-toggle" role="group" aria-label="Association score period">${[['ytd','YTD Comparisons'],['annual','Annual Totals']].map(([key,label])=>`<button type="button" data-association-period="${key}" class="${scoresAssociationPeriod===key?'active':''}">${label}</button>`).join('')}</div></div><div class="scores-ranking-scroll"><div class="scores-ranking-head">${header('rank','Rank')}${header('association','Association')}${years.map((y,i)=>`${i?header('change-'+y,'% Change'):''}${header('year-'+y,y+(scoresAssociationPeriod==='annual'&&y===current?' YTD':''))}`).join('')}${header('share',current+' Share')}</div><div class="scores-ranking-list">${rows.map(r=>`<div class="scores-ranking-row" data-score-association="${esc(r.id||'unknown')}" data-association-scope="${esc(r.scope)}"><span>${r.rank}</span><strong>${esc(r.name)}</strong>${years.map((y,i)=>`${i?changeCell(r.years,y):''}<b data-association-year="${y}" data-association-score-count="${r.years[y]||0}">${fmt(r.years[y]||0)}</b>`).join('')}<span>${pct(totals[current]?r.scores/totals[current]:0)}</span></div>`).join('')}<div class="scores-ranking-row scores-association-total"><span></span><strong>Total</strong>${years.map((y,i)=>`${i?changeCell(totals,y):''}<b data-association-year-total="${y}">${fmt(totals[y]||0)}</b>`).join('')}<span>${totals[current]?'100.0%':'—'}</span></div></div></div></article><p class="live-source-note">Rank and share reflect ${current} YTD. % change compares each year with the previous year.${scoresAssociationPeriod==='annual'?' The 2026 change is omitted because a partial year cannot be compared with a full year.':''} Association and member classifications reflect records at extraction. Earlier years use historical exports; 2025–2026 retain the score totals used on the Totals page.</p></section>`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-association-period]');if(b){scoresAssociationPeriod=b.dataset.associationPeriod;render();}});
function liveScoresPage(){return `<div class="scores-page scores-live">${activeSub==='posting-mix'?liveScoresMix():activeSub==='associations'?liveScoresAssociations():liveScoresTotals()}<footer class="scores-data-footer">${liveScoresNote()}${liveScoresDetails()}</footer></div>`}
function liveScoresHomeCard(){const data=liveScoreData('all','all'),d=liveScoreSummary(data);return `<article class="card half summary-trend-card performance-card scores"><div class="performance-band"><span>Scores Posted</span><button class="trend-title-link" data-open-tab="scores" type="button">Open Scores →</button></div><div class="performance-card-body">${liveScoresPerformance(d,true)}${liveScoresTrendChart(data,true)}</div></article>`}

function liveScoreApiData(){const data=liveScoreData();return {...data,months:data.months.map(m=>({...m,count:Object.values(m.apiAccounts||{}).reduce((n,v)=>n+v,0),breakdowns:{...m.breakdowns,api:m.apiAccounts||{}}}))};}
let scoreApiTableSort={key:'count',direction:-1};
function liveScoreApiAccounts(){const totals=new Map();for(const month of liveScoreSummary().current)for(const [name,n] of Object.entries(month.apiAccounts||{}))totals.set(name,(totals.get(name)||0)+n);return [...totals].map(([name,count])=>({name,count}));}
function scoreApiAccountRows(rows,total,query=''){
  const selected=rows.filter(r=>r.name.toLowerCase().includes(query.trim().toLowerCase()));
  selected.sort((a,b)=>(scoreApiTableSort.key==='name'?a.name.localeCompare(b.name):a.count-b.count)*scoreApiTableSort.direction||a.name.localeCompare(b.name));
  return selected.length?selected.map(r=>`<tr><th scope="row">${esc(r.name)}</th><td data-api-account-count="${r.count}">${fmt(r.count)}</td><td>${pct(total?r.count/total:0)}</td></tr>`).join(''):'<tr><td colspan="3">No matching API accounts.</td></tr>';
}
function liveScoreApiAccountPanel(){const rows=liveScoreApiAccounts(),total=rows.reduce((n,r)=>n+r.count,0);return `<section class="scores-api-account-panel"><h3>All API accounts · January–August 2026</h3><label class="scores-api-search">Search API accounts<input type="search" placeholder="Search account name" autocomplete="off" data-api-account-search></label><p data-api-search-summary>${fmt(rows.length)} accounts · ${fmt(total)} API scores</p><div class="scores-api-table-scroll"><table><thead><tr><th scope="col"><button type="button" data-api-table-sort="name">API account ↕</button></th><th scope="col"><button type="button" data-api-table-sort="count">Scores ↕</button></th><th scope="col"><button type="button" data-api-table-sort="share">Share of API scores ↕</button></th></tr></thead><tbody>${scoreApiAccountRows(rows,total)}</tbody></table></div></section>`;}
function updateScoreApiTable(){const panel=document.querySelector('.scores-api-account-panel');if(!panel)return;const rows=liveScoreApiAccounts(),total=rows.reduce((n,r)=>n+r.count,0),query=panel.querySelector('input').value;panel.querySelector('tbody').innerHTML=scoreApiAccountRows(rows,total,query);const filtered=rows.filter(r=>r.name.toLowerCase().includes(query.trim().toLowerCase()));panel.querySelector('[data-api-search-summary]').textContent=`${fmt(filtered.length)} of ${fmt(rows.length)} accounts · ${fmt(filtered.reduce((n,r)=>n+r.count,0))} scores shown`;for(const th of panel.querySelectorAll('thead th')){const key=th.querySelector('button').dataset.apiTableSort;th.setAttribute('aria-sort',key===scoreApiTableSort.key?(scoreApiTableSort.direction===1?'ascending':'descending'):'none');}}
document.addEventListener('input',e=>{if(e.target.matches?.('[data-api-account-search]'))updateScoreApiTable();});
document.addEventListener('click',e=>{const button=e.target.closest?.('[data-api-table-sort]');if(!button)return;const key=button.dataset.apiTableSort;scoreApiTableSort.direction=scoreApiTableSort.key===key?-scoreApiTableSort.direction:key==='name'?1:-1;scoreApiTableSort.key=key;updateScoreApiTable();});

document.addEventListener('click',event=>{const button=event.target.closest?.('[data-scroll-api-more]');if(!button)return;const list=button.parentElement.querySelector('.scores-api-all-scroll');list?.scrollBy({top:list.clientHeight*.8,behavior:'smooth'});});
document.addEventListener('scroll',event=>{const list=event.target;if(!list.matches?.('.scores-api-all-scroll'))return;const cue=list.parentElement.querySelector('[data-scroll-api-more]');if(cue)cue.hidden=list.scrollTop+list.clientHeight>=list.scrollHeight-2;},true);
